/**
 * A p-code operator use-def node.
 * <p>
 * For a table of p-code ops, use-def nodes, and code generators, see {@link OpGen}.
 */
public interface JitOp {

	static string toString(PcodeOp op, PcodeUseropSymbolMap symbols) {
		Varnode @out = op.getOutput();
		if (op.getOpcode() == PcodeOp.CALLOTHER) {
			Varnode opIndex = op.getInput(0);
			string opName = symbols.getUseropName((int) opIndex.getOffset());
			return "%s = %s '%s' %s".formatted(
				@out == null ? " --- " : @out.toString(symbols.language()),
				op.getMnemonic(),
				opName == null ? "<unk>" : opName,
				Stream.of(op.getInputs())
						.skip(1)
						.map(in => @in.toString(symbols.language()))
						.collect(Collectors.joining(", ")));
		}
		return "%s = %s %s".formatted(
			@out == null ? " --- " : @out.toString(symbols.language()),
			op.getMnemonic(),
			Stream.of(op.getInputs())
					.map(in => @in.toString(symbols.language()))
					.collect(Collectors.joining(", ")));
	}

	/**
	 * Create a use-def node for a nop or unimplemented op.
	 * 
	 * @param op the p-code op
	 * @return the use-def node
	 */
	static JitOp stubOp(PcodeOp op) {
		if (op is NopPcodeOp) {
			return new JitNopOp(op);
		}
		switch (op.getOpcode()) {
			case PcodeOp.UNIMPLEMENTED: return new JitUnimplementedOp(op);
			default: throw new UnsupportedOperationException(
				"Unrecognized stub op: " + op.getMnemonic());
		};
	}

	/**
	 * Create a use-def node for a unary p-coe op
	 * 
	 * @param op the p-code op
	 * @param out the (pre-made) output operand use-def node
	 * @param u the input operand use-def node
	 * @return the use-def node
	 */
	static JitUnOp unOp(PcodeOp op, JitOutVar @out, JitVal u) {
		switch (op.getOpcode()) {
			case PcodeOp.COPY: return new JitCopyOp(op, @out, u);

			case PcodeOp.INT_ZEXT: return new JitIntZExtOp(op, @out, u);
			case PcodeOp.INT_SEXT: return new JitIntSExtOp(op, @out, u);
			case PcodeOp.INT_2COMP: return new JitInt2CompOp(op, @out, u);
			case PcodeOp.INT_NEGATE: return new JitIntNegateOp(op, @out, u);

			case PcodeOp.POPCOUNT: return new JitPopCountOp(op, @out, u);
			case PcodeOp.LZCOUNT: return new JitLzCountOp(op, @out, u);

			case PcodeOp.BOOL_NEGATE: return new JitBoolNegateOp(op, @out, u);

			case PcodeOp.FLOAT_NAN: return new JitFloatNaNOp(op, @out, u);
			case PcodeOp.FLOAT_NEG: return new JitFloatNegOp(op, @out, u);
			case PcodeOp.FLOAT_ABS: return new JitFloatAbsOp(op, @out, u);
			case PcodeOp.FLOAT_SQRT: return new JitFloatSqrtOp(op, @out, u);

			case PcodeOp.FLOAT_INT2FLOAT: return new JitFloatInt2FloatOp(op, @out, u);
			case PcodeOp.FLOAT_FLOAT2FLOAT: return new JitFloatFloat2FloatOp(op, @out, u);
			case PcodeOp.FLOAT_TRUNC: return new JitFloatTruncOp(op, @out, u);
			case PcodeOp.FLOAT_CEIL: return new JitFloatCeilOp(op, @out, u);
			case PcodeOp.FLOAT_FLOOR: return new JitFloatFloorOp(op, @out, u);
			case PcodeOp.FLOAT_ROUND: return new JitFloatRoundOp(op, @out, u);

			default: throw new UnsupportedOperationException(
				"Unrecognized un op: " + op.getMnemonic());
		};
	}

	/**
	 * Create a use-def node for a binary p-coe op
	 * 
	 * @param op the p-code op
	 * @param out the (pre-made) output operand use-def node
	 * @param l the left input operand use-def node
	 * @param r the right input operand use-def node
	 * @return the use-def node
	 */
	static JitDefOp binOp(PcodeOp op, JitOutVar @out, JitVal l, JitVal r) {
		switch (op.getOpcode()) {
			case PcodeOp.INT_EQUAL: return new JitIntEqualOp(op, @out, l, r);
			case PcodeOp.INT_NOTEQUAL: return new JitIntNotEqualOp(op, @out, l, r);
			case PcodeOp.INT_SLESS: return new JitIntSLessOp(op, @out, l, r);
			case PcodeOp.INT_SLESSEQUAL: return new JitIntSLessEqualOp(op, @out, l, r);
			case PcodeOp.INT_LESS: return new JitIntLessOp(op, @out, l, r);
			case PcodeOp.INT_LESSEQUAL: return new JitIntLessEqualOp(op, @out, l, r);
			case PcodeOp.INT_ADD: return new JitIntAddOp(op, @out, l, r);
			case PcodeOp.INT_SUB: return new JitIntSubOp(op, @out, l, r);
			case PcodeOp.INT_CARRY: return new JitIntCarryOp(op, @out, l, r);
			case PcodeOp.INT_SCARRY: return new JitIntSCarryOp(op, @out, l, r);
			case PcodeOp.INT_SBORROW: return new JitIntSBorrowOp(op, @out, l, r);
			case PcodeOp.INT_XOR: return new JitIntXorOp(op, @out, l, r);
			case PcodeOp.INT_AND: return new JitIntAndOp(op, @out, l, r);
			case PcodeOp.INT_OR: return new JitIntOrOp(op, @out, l, r);
			case PcodeOp.INT_LEFT: return new JitIntLeftOp(op, @out, l, r);
			case PcodeOp.INT_RIGHT: return new JitIntRightOp(op, @out, l, r);
			case PcodeOp.INT_SRIGHT: return new JitIntSRightOp(op, @out, l, r);
			case PcodeOp.INT_MULT: return new JitIntMultOp(op, @out, l, r);
			case PcodeOp.INT_DIV: return new JitIntDivOp(op, @out, l, r);
			case PcodeOp.INT_SDIV: return new JitIntSDivOp(op, @out, l, r);
			case PcodeOp.INT_REM: return new JitIntRemOp(op, @out, l, r);
			case PcodeOp.INT_SREM: return new JitIntSRemOp(op, @out, l, r);

			case PcodeOp.BOOL_XOR: return new JitBoolXorOp(op, @out, l, r);
			case PcodeOp.BOOL_AND: return new JitBoolAndOp(op, @out, l, r);
			case PcodeOp.BOOL_OR: return new JitBoolOrOp(op, @out, l, r);

			case PcodeOp.FLOAT_EQUAL: return new JitFloatEqualOp(op, @out, l, r);
			case PcodeOp.FLOAT_NOTEQUAL: return new JitFloatNotEqualOp(op, @out, l, r);
			case PcodeOp.FLOAT_LESS: return new JitFloatLessOp(op, @out, l, r);
			case PcodeOp.FLOAT_LESSEQUAL: return new JitFloatLessEqualOp(op, @out, l, r);

			case PcodeOp.FLOAT_ADD: return new JitFloatAddOp(op, @out, l, r);
			case PcodeOp.FLOAT_DIV: return new JitFloatDivOp(op, @out, l, r);
			case PcodeOp.FLOAT_MULT: return new JitFloatMultOp(op, @out, l, r);
			case PcodeOp.FLOAT_SUB: return new JitFloatSubOp(op, @out, l, r);

			case PcodeOp.SUBPIECE => new JitSubPieceOp(op, @out, l,
				((JitConstVal) r).value().intValue());

			default: throw new UnsupportedOperationException(
				"Unrecognized bin op: " + op.getMnemonic());
		};
	}

	/**
	 * Render this op using symbols for varnodes and userop names
	 * 
	 * @param symbols the userop symbols and language
	 * @return the string
	 */
	string toString(PcodeUseropSymbolMap symbols);

	/**
	 * The p-code op represented by this use-def node
	 * 
	 * @return the p-code op
	 */
	PcodeOp op();

	/**
	 * Indicates the operation can be removed if its output is never used.
	 * 
	 * @return true if removable
	 */
	bool canBeRemoved();

	/**
	 * The input operand use-def nodes in some defined order
	 * 
	 * @return the list of inputs
	 */
	List<JitVal> inputs();

	/**
	 * Get the required type behavior for the input at the given position in {@link #inputs()}
	 * 
	 * @param position the input position
	 * @return the behavior
	 */
	JitTypeBehavior typeFor(int position);

	/**
	 * Add this op to the {@link JitVal#uses()} of each input operand, and (if applicable) set the
	 * {@link JitOutVar#definition()} of the output operand to this op.
	 */
	void link();

	/**
	 * Remove this op from the {@link JitVal#uses()} of each input operand, and (if applicable)
	 * unset the {@link JitOutVar#definition()} of the output operand.
	 */
	void unlink();
}
